1	/**
2	 * Custom entry rendering example.
3	 *
4	 * Shows how to render durable extension data inside the chat without sending it
5	 * to the LLM. Custom entries are stored in the session via pi.appendEntry() and
6	 * rendered in interactive mode via pi.registerEntryRenderer().
7	 *
8	 * Usage: /status-card [message]
9	 */
10	
11	import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
12	import { Box, Text } from "@earendil-works/pi-tui";
13	
14	interface StatusCardData {
15		message: string;
16		timestamp: number;
17	}
18	
19	export default function (pi: ExtensionAPI) {
20		pi.registerEntryRenderer<StatusCardData>("status-card", (entry, { expanded }, theme) => {
21			const data = entry.data ?? { message: "No data", timestamp: Date.now() };
22			const box = new Box(1, 1, (text) => theme.bg("customMessageBg", text));
23			box.addChild(new Text(`${theme.fg("accent", "[status]")} ${data.message}`, 0, 0));
24	
25			if (expanded) {
26				box.addChild(new Text(theme.fg("dim", new Date(data.timestamp).toLocaleString()), 0, 0));
27			}
